ROW.COLUMN:
/* Dataset Name: ML_PolicieswithRefunds_fCU_dsCUST - 11469121 ** - This dataset selects customers for which insuarance policies of interest were created during interested - period of time */ select g.CUST_INTRL_ID, g.Effctv_Risk_Lvl, g.CUST_SEQ_ID, g.Actvty_Risk_Lvl, g.Tot_Refund_Amt, g.Tot_Refund_Ct, g.Tot_Refund_Prctg, g.Overall_Risk, g.Tot_Expected_Amt, g.Tot_Expected_Ct
from (
select w.CUST_INTRL_ID, max(w.CUST_EFCTV_RISK_NB) as Effctv_Risk_Lvl, max(w.CUST_SEQ_ID) as CUST_SEQ_ID, max(w.NSRNC_TRXN_ACTVY_RISK_NB) as Actvty_Risk_Lvl, sum(w.TRXN_BASE_AM) as Tot_Refund_Amt, count(distinct w.NSRNC_TRXN_SEQ_ID) as Tot_Refund_Ct, --Bug 34973047 case when max(w.Expected_Amt) > 0 then sum(w.TRXN_BASE_AM)*100/max(w.Expected_Amt) else 0 end as Tot_Refund_Prctg, case when (max(w.CUST_EFCTV_RISK_NB) >= @Effctv_Risk_Cutoff_Lvl and max(w.NSRNC_TRXN_ACTVY_RISK_NB) >= @Actvty_Risk_Cutoff_Lvl) then 'HR' when (max(w.CUST_EFCTV_RISK_NB) < @Effctv_Risk_Cutoff_Lvl and max(w.NSRNC_TRXN_ACTVY_RISK_NB) < @Actvty_Risk_Cutoff_Lvl) then 'RR' else 'MR' end as Overall_Risk, --Bug 34973047 max(w.Expected_Amt) as Tot_Expected_Amt, max(w.Expected_Ct) as Tot_Expected_Ct
from ( select cust.CUST_SEQ_ID, cust.CUST_INTRL_ID, cust.CUST_EFCTV_RISK_NB, t.NSRNC_TRXN_ACTVY_RISK_NB, t.TRXN_BASE_AM, t.NSRNC_TRXN_SEQ_ID, t.DATA_DUMP_DT, -- While calculating expected payments the scenario includes Initial Payment for the policies that are Multiple Policies -- and /*younger than*/ in Lookback Period, for all others (Single Premium Policies and Multiple Premium Policies Initial Payment/*older than*/ out of Lookback Period) -- it excludes Initial Payment. (case when prdct.PREM_TYPE_CD = 2 and -- Multiple policy code --Bug 34973047 (plcy.INIT_DEPST_DT > add_months(k.CLNDR_DT, -@Lookback_Period)) then plcy.INIT_DEPST_BASE_AM else 0 end) -- + plcy.PREM_BASE_AM * (case plcy.PREM_PERIOD_TYPE_CD when 'W' then (k.CLNDR_DT - add_months(k.CLNDR_DT, -@Lookback_Period))/7 -- Weekly when 'B' then (k.CLNDR_DT - add_months(k.CLNDR_DT, -@Lookback_Period))/14 -- Every two weeks when 'M' then @Lookback_Period -- Monthly when 'T' then @Lookback_Period*2 -- Two times per month when 'I' then @Lookback_Period/2 -- Every two months when 'Q' then @Lookback_Period/3 -- Quarterly when 'S' then @Lookback_Period/6 -- Two times per year when 'A' then 1 -- annualy else 1 end) as Expected_Amt,
(case when prdct.PREM_TYPE_CD = 2 and -- Multiple policy code --Bug 34973047 (plcy.INIT_DEPST_DT > add_months(k.CLNDR_DT, -@Lookback_Period)) then 1 else 0 end) + case plcy.PREM_PERIOD_TYPE_CD when 'W' then (k.CLNDR_DT - add_months(k.CLNDR_DT, -@Lookback_Period))/7 -- Weekly when 'B' then (k.CLNDR_DT - add_months(k.CLNDR_DT, -@Lookback_Period))/14 -- Every two weeks when 'M' then @Lookback_Period -- Monthly when 'T' then @Lookback_Period*2 -- Two times per month when 'I' then @Lookback_Period/2 -- Every two months when 'Q' then @Lookback_Period/3 -- Quarterly when 'S' then @Lookback_Period/6 -- Two times per year when 'A' then 1 -- annualy else 1 end as Expected_Ct
from @MINER@.CUST cust inner join @MINER@.INSURANCE_POLICY_CUST plcy_cust on (plcy_cust.CUST_INTRL_ID = cust.CUST_INTRL_ID) inner join @MINER@.INSURANCE_POLICY plcy on (plcy.NSRNC_PLCY_INTRL_ID = plcy_cust.NSRNC_PLCY_INTRL_ID) inner join @MINER@.INSURANCE_PRODUCT prdct on (prdct.NSRNC_PRDCT_INTRL_ID = plcy.NSRNC_PRDCT_INTRL_ID) inner join @MINER@.INSURANCE_TRXN t on (t.NSRNC_PLCY_INTRL_ID = plcy.NSRNC_PLCY_INTRL_ID) inner join @MANTAS@.KDD_CAL k on (k.CLNDR_DAY_AGE=0 and k.CLNDR_NM = 'SYSCAL') where -- Current Date - Max Policy Age <= Policy Issue Date months_between(k.CLNDR_DT, plcy.NSRNC_PLCY_ISSUE_DT) <= @Max_Policy_Age -- Lookback Period Tunable Filter and t.TRXN_DT <= (select k.CLNDR_DT from @MANTAS@.KDD_CAL k where k.CLNDR_DAY_AGE=0 and k.CLNDR_NM = 'SYSCAL') and t.TRXN_DT > (select add_months(k.CLNDR_DT, -@Lookback_Period) from @MANTAS@.KDD_CAL k where k.CLNDR_DAY_AGE=0 and k.CLNDR_NM = 'SYSCAL') -- All Insurance Types Tunable Filter and (@All_Insurance_Types='Y' or prdct.NSRNC_TYPE_CD in (@Included_Insurance_Types)) -- Included Premium Types Tunable Filter and (prdct.PREM_TYPE_CD in (@Included_Premium_Types)) and t.MANTAS_TRXN_PURP_CD = 'REFUND' -- Jurisdiction Tunable Filter and (@All_Jurisdictions='Y' or cust.JRSDCN_CD in (@Included_Jurisdiction_Codes)) -- Exclude Exempted Customers and cust.CUST_EFCTV_RISK_NB <> -2 -- Exclude Variables and Others, Not Listed Above premium payments and plcy.PREM_PERIOD_TYPE_CD not in ('O', 'R') -- Exclude Surrendered Policies and plcy.PLCY_SRNDR_DT is null ) w group by w.CUST_INTRL_ID having -- Frequency Period min(DATA_DUMP_DT) <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and max(DATA_DUMP_DT) > (select add_months(b.CLNDR_DT, -1) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) ) g where -- determine if divisor is equal to zero -- Bug 34973047 -- g.Tot_Expected_Amt > 0 ( ( g.Overall_Risk = 'HR' -- the minimum refund made to be considered for alert generation and g.Tot_Refund_Amt >= @HR_Min_Refund_Amt -- the minimum number of refund transactions and g.Tot_Refund_Ct >= @HR_Min_Refund_Ct -- the minimum percentage of aggregated refund amount over expected aggregated amount of premium payments -- Bug 34973047 if expected amount is 0 but refund was executed - we use -- 'dummy huge value 9999999' to exceed any value in @HR_Min_Refund_Amt_Prctg, for alerting this case and case when g.Tot_Expected_Amt > 0 then g.Tot_Refund_Amt*100/g.Tot_Expected_Amt else 9999999 end >= @HR_Min_Refund_Amt_Prctg ) OR ( g.Overall_Risk = 'RR' -- the minimum refund made to be considered for alert generation and g.Tot_Refund_Amt >= @RR_Min_Refund_Amt -- the minimum number of refund transactions and g.Tot_Refund_Ct >= @RR_Min_Refund_Ct -- the minimum percentage of aggregated refund amount over expected aggregated amount of premium payments -- Bug 34973047 and case when g.Tot_Expected_Amt > 0 then g.Tot_Refund_Amt*100/g.Tot_Expected_Amt else 9999999 end >= @RR_Min_Refund_Amt_Prctg ) OR ( g.Overall_Risk = 'MR' -- the minimum refund made to be considered for alert generation and g.Tot_Refund_Amt >= @MR_Min_Refund_Amt -- the minimum number of refund transactions and g.Tot_Refund_Ct >= @MR_Min_Refund_Ct -- the minimum percentage of aggregated refund amount over expected aggregated amount of premium payments -- Bug 34973047 and case when g.Tot_Expected_Amt > 0 then g.Tot_Refund_Amt*100/g.Tot_Expected_Amt else 9999999 end >= @MR_Min_Refund_Amt_Prctg ) )
